//! The OID registry: look up and print ASN.1 object identifiers.
//!
//! Ported from `lib/oid_registry.c` and `include/linux/oid_registry.h`,
//! Copyright Red Hat, Inc. The table of known OIDs is generated by
//! `scripts/gen_oid_registry.py` into [`crate::oid_registry_data`], as Linux
//! generates `oid_registry_data.c` at build time.
//!
//! OIDs are passed as their ASN.1 content octets (the TLV value, without the
//! tag and length). `sprint_oid()` writes into a caller's buffer with the
//! C `snprintf()` truncation rules, and returns the length in bytes.

use crate::errno::{EBADMSG, ENOBUFS, Errno};
use crate::oid_registry_data::{OID_DATA, OID_INDEX, OID_NR, OID_SEARCH_TABLE, OID_VARIANTS};

pub use crate::oid_registry_data::Oid;

/// `ASN1_OID`: the ASN.1 tag of an object identifier.
const ASN1_OID: u8 = 6;

/// `look_up_OID()`: the registry entry for `data`, or `Oid::OID__NR` if the
/// OID is not one the kernel knows.
///
/// The table is a binary search on an 8-bit hash of the octets, and within
/// one hash value on length and then bytes compared from the end.
pub fn look_up_oid(data: &[u8]) -> Oid {
    let datasize = data.len();

    // C computes this in an `unsigned int`; `datasize - 1` wraps for empty data.
    let mut hash = (datasize as u32).wrapping_sub(1);
    for &octet in data {
        hash = hash.wrapping_add(u32::from(octet) * 33);
    }
    hash = (hash >> 24) ^ (hash >> 16) ^ (hash >> 8) ^ hash;
    let hash = (hash & 0xff) as u8;

    let mut i = 0;
    let mut k = OID_NR;
    while i < k {
        let j = (i + k) / 2;
        let (xhash, oid) = OID_SEARCH_TABLE[j];
        if xhash > hash {
            k = j;
            continue;
        }
        if xhash < hash {
            i = j + 1;
            continue;
        }
        let oid = usize::from(oid);
        let start = usize::from(OID_INDEX[oid]);
        let len = usize::from(OID_INDEX[oid + 1]) - start;
        if len > datasize {
            k = j;
            continue;
        }
        if len < datasize {
            i = j + 1;
            continue;
        }
        let mut ordering = core::cmp::Ordering::Equal;
        let mut remaining = len;
        while remaining > 0 {
            remaining -= 1;
            let a = OID_DATA[start + remaining];
            let b = data[remaining];
            ordering = a.cmp(&b);
            if ordering != core::cmp::Ordering::Equal {
                break;
            }
        }
        match ordering {
            core::cmp::Ordering::Greater => k = j,
            core::cmp::Ordering::Less => i = j + 1,
            core::cmp::Ordering::Equal => return OID_VARIANTS[oid],
        }
    }
    Oid::OID__NR
}

/// `parse_OID()`: check that `data` is a whole ASN.1 OID TLV.
///
/// The C function takes an output `enum OID *` but never sets it, so this
/// port only performs the check.
pub fn parse_oid(data: &[u8]) -> Result<(), Errno> {
    // `v[1] != datasize - 2` in C: the length octet must be the content size.
    if data.len() < 3 || data[0] != ASN1_OID || usize::from(data[1]) != data.len() - 2 {
        return Err(EBADMSG);
    }
    Ok(())
}

/// A bounded writer that behaves like the C `snprintf()` into a buffer.
///
/// It keeps the first `cap - 1` bytes, always NUL-terminates a non-empty
/// buffer, and counts every byte written in `total`.
struct Snprintf<'a> {
    buf: &'a mut [u8],
    total: usize,
}

impl Snprintf<'_> {
    fn put(&mut self, byte: u8) {
        let cap = self.buf.len();
        if self.total + 1 < cap {
            self.buf[self.total] = byte;
        }
        self.total += 1;
    }

    fn put_str(&mut self, s: &str) {
        for &b in s.as_bytes() {
            self.put(b);
        }
    }

    fn put_u64(&mut self, mut v: u64) {
        let mut digits = [0u8; 20];
        let mut n = 0;
        loop {
            digits[n] = b'0' + (v % 10) as u8;
            n += 1;
            v /= 10;
            if v == 0 {
                break;
            }
        }
        for &d in digits[..n].iter().rev() {
            self.put(d);
        }
    }

    /// Finishes the write: NUL-terminate what fits.
    fn finish(self) -> usize {
        let cap = self.buf.len();
        if cap > 0 {
            self.buf[self.total.min(cap - 1)] = 0;
        }
        self.total
    }
}

/// `sprint_oid()`: write the dotted form of `data` (`1.2.840.113549`) into
/// `buffer` and return the number of characters, not counting the NUL.
///
/// A segment that does not fit gives `ENOBUFS`. Malformed content writes
/// `(bad)` and gives `EBADMSG`.
pub fn sprint_oid(data: &[u8], buffer: &mut [u8]) -> Result<usize, Errno> {
    let bufsize = buffer.len();
    let mut out = Snprintf {
        buf: buffer,
        total: 0,
    };

    let Some((&first, mut rest)) = data.split_first() else {
        out.put_str("(bad)");
        out.finish();
        return Err(EBADMSG);
    };

    // The first octet packs the first two arcs.
    out.put_u64(u64::from(first / 40));
    out.put(b'.');
    out.put_u64(u64::from(first % 40));
    if out.total >= bufsize {
        return Err(ENOBUFS);
    }

    while let Some((&n, tail)) = rest.split_first() {
        rest = tail;
        let mut num = u64::from(n & 0x7f);
        let mut more = n & 0x80 != 0;
        while more {
            let Some((&n, tail)) = rest.split_first() else {
                out.put_str("(bad)");
                out.finish();
                return Err(EBADMSG);
            };
            rest = tail;
            num = (num << 7) | u64::from(n & 0x7f);
            more = n & 0x80 != 0;
        }
        out.put(b'.');
        out.put_u64(num);
        if out.total >= bufsize {
            return Err(ENOBUFS);
        }
    }

    Ok(out.finish())
}
